\begin{tikzpicture}[font=\sffamily, scale=0.8]
  % Coordinates based on geometry
  % Let D be at origin (0,0)
  % B is due South of D, so B is at (0, -BD)
  % Let's calculate the triangle BCD first:
  % CD = 9, angle DBC = 30°, angle DCB = 85°
  % Angle BDC = 180 - 30 - 85 = 65°
  % By sine rule in BCD: BC / sin(65°) = 9 / sin(30°) => BC = 18 * sin(65°) ≈ 16.31
  % BD / sin(85°) = 9 / sin(30°) => BD = 18 * sin(85°) ≈ 17.91

  \coordinate (D) at (0,0);
  \coordinate (B) at (0,-5.97); % scaled BD for visual clarity, say length ~ 6 cm representing ~ 17.9m

  % C is at angle 65° from DB (upwards and rightwards from D)
  % Let's place C using polar relative to D: distance CD = 3 cm (scale), angle = 180° - 65° = 115°? No, D is north of B, so vector DB is downwards.
  % Vector DC makes an angle with DB. In triangle BCD, D is top vertex (since B is south of D? Wait, D is north of B, so D is above B).
  % Let's set D = (0,4), B = (0,-2).
  % Angle BDC = 65°. Since B is south, North is up (+y). D is north of B.
  % C is such that CD = 9, angle BDC = 65° (to the east, say).
  \coordinate (D) at (0,4);
  \coordinate (B) at (0,-1.5);
  \coordinate (C) at ({3*sin(65)}, {4 - 3*cos(65)}); % Wait, let's just place visually accurate

  % Re-define exact positions for clear drawing
  \coordinate (D) at (1, 4.5);
  \coordinate (B) at (1, -1.5);
  % CD = 9 m, AD = 6 m, AB = 14.5 m
  % Let's place points to look like a standard geometry problem diagram
  \coordinate (D) at (2, 5);
  \coordinate (B) at (2, -1);
  \coordinate (C) at (6.5, 3.2);
  \coordinate (A) at (-3, 3);

  % Draw triangles on the ground
  \draw[thick] (A) -- (D) -- (B) -- cycle;
  \draw[thick] (B) -- (C) -- (D);
  \draw[thick] (A) -- (B);

  % Labels for points
  \node[above] at (D) {D};
  \node[below] at (B) {B};
  \node[right] at (C) {C};
  \node[left] at (A) {A};

  % North arrow at D
  \draw[->, thick] (D) -- ++(0, 1.2) node[above] {North};

  % Dimensions and angles
  \node[left] at ($(A)!0.5!(D)$) {6 m};
  \node[above left] at ($(A)!0.5!(B)$) {14.5 m};
  \node[above right] at ($(D)!0.5!(C)$) {9 m};

  % Angle arcs
  \draw (B) ++(0:0.5) arc (0:30:0.5);
  % Approximate visual angles for illustration
  \draw ($(B)+(0.3,0)$) arc (0:35:0.5);
  \node at ($(B)+(0.7,0.3)$) {$30^\circ$};

  \draw ($(C)+(-130:0.5)$) arc (-130:-45:0.5);
  % Just label near C
  \node at ($(C)+(-0.5,-0.5)$) {$85^\circ$};

  % Additional helper for D north of B line extension if needed
  \draw[dashed] (D) -- (B);

\end{tikzpicture}
